pm.test("Cliente 1 encolado en Fila Virtual", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    const json = pm.response.json();
    const turno = json.tokenAcceso || json.token || json.turnoFila || json.codigoTurno || json.id || json.turnoId || "";
    pm.expect(turno, "No se encontró token de fila en la respuesta").to.not.be.empty;
    pm.collectionVariables.set("turnoFilaC1", String(turno));
});

pm.test("GET Estado en Fila Virtual Cliente 1 devuelve 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Cliente 2 encolado en Fila Virtual", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    const json = pm.response.json();
    const turno = json.tokenAcceso || json.token || json.turnoFila || json.codigoTurno || json.id || json.turnoId || "";
    pm.expect(turno, "No se encontró token de fila en la respuesta").to.not.be.empty;
    pm.collectionVariables.set("turnoFilaC2", String(turno));
});

pm.test("GET Estado en Fila Virtual Cliente 2 devuelve 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Orden Alta Demanda (Cliente 1) creada correctamente", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    const json = pm.response.json();
    const id = json.id ?? json.idOrden ?? json.ordenId;
    pm.expect(id, "Debe devolver ID de la orden").to.not.be.undefined;
    pm.collectionVariables.set("ordenAltaDemandaId", String(id));
});

pm.test("Reserva creada correctamente", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    const json = pm.response.json();
    const id = json.id ?? json.idReserva ?? json.reservaId;
    if (id !== undefined) pm.collectionVariables.set("reservaId", String(id));
});

pm.test("Entrada Numerada creada correctamente", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    const raw = pm.response.json();
    const item = Array.isArray(raw) ? raw[0] : raw;
    if (item) {
        const id = item.id ?? item.idEntrada ?? item.entradaId;
        if (id !== undefined) pm.collectionVariables.set("entradaNumeradaId", String(id));
        const qr = item.codigoQr || item.qr || item.codigo;
        if (qr) pm.collectionVariables.set("codigoQrEntradaNumerada", String(qr));
    }
});

pm.sendRequest({
    url: pm.collectionVariables.get("base_url") + "/api/pagos",
    method: "GET",
    header: {
        "Authorization": "Bearer " + pm.collectionVariables.get("tokenCliente1")
    }
}, function (err, res) {
    if (!err && res.code === 200) {
        const aceptados = res.json().filter(p => (p.estado || "").toUpperCase() === "ACEPTADO");
        if (aceptados.length >= 2) {
            pm.collectionVariables.set("reservaPagadaC1", String(aceptados[aceptados.length - 3]?.idReserva ?? aceptados[aceptados.length - 2].idReserva));
            pm.collectionVariables.set("reservaPagadaC2", String(aceptados[aceptados.length - 2].idReserva));
        } else if (aceptados.length === 1) {
            pm.collectionVariables.set("reservaPagadaC1", String(aceptados[0].idReserva));
            pm.collectionVariables.set("reservaPagadaC2", String(aceptados[0].idReserva));
        }
    }
});

pm.test("Entrada No Numerada creada correctamente", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    const raw = pm.response.json();
    const item = Array.isArray(raw) ? raw[0] : raw;
    if (item) {
        const id = item.id ?? item.idEntrada ?? item.entradaId;
        if (id !== undefined) pm.collectionVariables.set("entradaNoNumeradaId", String(id));
    }
});

pm.sendRequest({
    url: pm.collectionVariables.get("base_url") + "/api/pagos",
    method: "GET",
    header: {
        "Authorization": "Bearer " + pm.collectionVariables.get("tokenCliente2")
    }
}, function (err, res) {
    if (!err && res.code === 200) {
        const aceptados = res.json().filter(p => (p.estado || "").toUpperCase() === "ACEPTADO");
        if (aceptados.length >= 2) {
            pm.collectionVariables.set("reservaPagadaC1", String(aceptados[aceptados.length - 3]?.idReserva ?? aceptados[aceptados.length - 2].idReserva));
            pm.collectionVariables.set("reservaPagadaC2", String(aceptados[aceptados.length - 2].idReserva));
        } else if (aceptados.length === 1) {
            pm.collectionVariables.set("reservaPagadaC1", String(aceptados[0].idReserva));
            pm.collectionVariables.set("reservaPagadaC2", String(aceptados[0].idReserva));
        }
    }
});

pm.test("GET Listado de Pagos devuelve 200 OK", function () {
    pm.response.to.have.status(200);
    const lista = pm.response.json();
    const aceptado = [...lista].reverse().find(p => (p.estado || "").toUpperCase() === "ACEPTADO");
    pm.expect(aceptado, "No hay ningún pago ACEPTADO disponible para reembolsar").to.not.be.undefined;
    pm.collectionVariables.set("reservaPagadaId", String(aceptado.idReserva));
});
